INSERT INTO public.kb_knowledge (url, url_hash, source_type, title, summary, key_points, tags, market, vertical, status, added_by, processed_at)
VALUES
('https://www.marketsandata.com/industry-reports/india-sneakers-market', 'kg_intel_india_sneaker_market_usd_3_88b_fy2024_to', 'web', 'India sneaker market: USD 3.88B (FY2024) to USD 5.93B (FY2032) at 5.45% CAGR', 'India''s sneaker market was valued at USD 3.88 billion in FY2024 and is projected to reach USD 5.93 billion by FY2032, growing at a 5.45% CAGR for FY2025-FY2032, per Markets and Data''s India Sneakers Market report — figures re-verified as cited in Business Today''s September 29, 2025 feature on custom sneakers. Sneakers now make up roughly 20-25% of India''s footwear industry per Markets and Data''s blog on the India sneaker boom. Growth drivers cited include a young demographic (420M+ Indians under 25), rising disposable incomes, celebrity/hip-hop influence, and hype culture. This is the single most-cited market-size figure across Indian sneaker coverage in 2025, making it a safe headline stat for Knickgasm decks and content.', '["USD 3.88B FY2024 \u2192 USD 5.93B FY2032, 5.45% CAGR (per Markets and Data, cited by Business Today, Sep 29 2025)", "Sneakers = ~20-25% of India''s footwear industry per Markets and Data", "Growth driven by Gen Z cohort of 420M+ Indians under 25, per Markets and Data blog", "Same figures independently cited by Inc42 (Apr 2025) and Business Today (Sep 2025)"]'::jsonb, '["market-size", "sneakers", "india", "cagr", "markets-and-data"]'::jsonb, 'IN', 'Sneakers', 'summarized', 'market-research', now()),
('https://inc42.com/features/how-sneaker-resellers-d2c-brands-are-cashing-in-on-indias-6-bn-boom/', 'kg_intel_inc42_resellers_and_d2c_brands_cashing_i', 'web', 'Inc42: resellers and D2C brands cashing in on India''s $6Bn sneaker boom', 'Inc42''s April 4, 2025 feature pegs India''s sneaker economy at a ~$6Bn opportunity, citing the $3.8Bn FY24 → $5.9Bn FY32 market at 5.45% CAGR, with the reseller segment growing at 10-11% CAGR and experts quoted anticipating at least 25% annual growth, all per Inc42. Named player metrics per Inc42: D2C brand Comet serves ~12,000 customers/month at INR 4,000-6,000 AOV; reseller Find Your Kicks moves 2,000-2,500 pairs/month at INR 10,000-11,000 AOV; Hustle Culture sold ~500 sneakers/month (March 2025) at INR 10,000-13,000 AOV after 5X growth from July 2024; Crepdog Crew runs 3 stores (Delhi, Mumbai, Hyderabad) with a 50-50 online/offline sales split. These are the best public AOV and volume benchmarks for the Indian sneaker D2C/resale channel and useful comps for Knickgasm''s INR 6K-15K custom price band.', '["Reseller market growing at 10-11% CAGR; experts predict 25%+ annual growth (per Inc42, Apr 2025)", "Comet: 12,000 customers/month, INR 4,000-6,000 AOV (per Inc42)", "Find Your Kicks: 2,000-2,500 pairs/month, INR 10,000-11,000 AOV (per Inc42)", "Crepdog Crew: 3 stores (Delhi, Mumbai, Hyderabad), 50/50 online-offline split (per Inc42)", "Resale AOVs (INR 10K-13K) validate Knickgasm''s custom-sneaker price band"]'::jsonb, '["resale", "d2c", "benchmarks", "aov", "inc42", "competitors"]'::jsonb, 'IN', 'Sneakers', 'summarized', 'market-research', now()),
('https://www.businesstoday.in/lifestyle/reviews/story/walking-on-art-how-a-pair-of-custom-sneakers-explains-indias-newest-cultural-obsession-496188-2025-09-29', 'kg_intel_business_today_sep_2025_custom_sneakers', 'web', 'Business Today (Sep 2025): custom sneakers are ''India''s newest cultural obsession''', 'Business Today''s September 29, 2025 review frames sneaker customization as India''s shift ''away from mass-produced hype towards hyper-personalisation,'' driven by Gen Z and millennials, per Business Today. The piece profiles Knickgasm itself: founded November 4, 2020 in Mumbai by Henil Kachhara and Shubh Parmar, bootstrapped, ''scaled over 20 times'' since launch, 1,000+ custom design variations, a decentralized artisan network across Tier 1/2/3 cities, and organic (non-paid) celebrity clients Shraddha Kapoor, Hardik Pandya, and Rohit Sharma — all per Business Today. It anchors the trend against the Markets and Data figure of USD 3.88B (FY2024) growing to USD 5.93B (FY2032) at 5.45% CAGR. This is first-party earned media validating Knickgasm as the category leader in national business press.', '["National business press frames customization as the next phase of India''s sneaker boom (Business Today, Sep 29 2025)", "Knickgasm profiled: founded Nov 4 2020, Mumbai, bootstrapped, 20x growth, 1,000+ designs (per Business Today)", "Celebrity clients Shraddha Kapoor, Hardik Pandya, Rohit Sharma acquired without paid partnerships (per Business Today)", "Trend anchored to Markets and Data''s USD 3.88B \u2192 5.93B market forecast"]'::jsonb, '["customization", "earned-media", "knickgasm-coverage", "trend", "business-today"]'::jsonb, 'IN', 'Sneakers', 'summarized', 'market-research', now()),
('https://www.khaleejtimes.com/lifestyle/arts/sneaker-customisation-art-fashion', 'kg_intel_khaleej_times_jul_2025_hand_painted_snea', 'web', 'Khaleej Times (Jul 2025): hand-painted sneaker customization goes mainstream, from Ranveer Singh to Jay-Z', 'Khaleej Times'' July 31, 2025 feature (updated Aug 2, 2025) documents hand-painted sneaker customization as wearable art, naming celebrities Ranveer Singh, Jay-Z, Sonam Kapoor, Pharrell Williams, and Shawn Mendes as custom-sneaker wearers, per Khaleej Times. It profiles Indian artists Sugandha Tyagi (Shoes Your Daddy, Delhi), Chaitanya Dixit (CHE), and Ridhii Makkar, who relocated to Mumbai to customize sneakers professionally, per Khaleej Times. Custom artwork pricing cited runs from ~AED 400 for simple designs to AED 1,000+ for intricate work (roughly INR 9,000-23,000), per Khaleej Times — a useful international price benchmark above typical Indian customizer rates. Tyagi attributes the shift over the past 4-5 years to a growing young population, streetwear culture, and desire for individuality, per Khaleej Times; the piece also notes Nike''s collaboration with Indian label Nor Black Nor White on bandhani-inspired designs.', '["Gulf/international press coverage of Indian sneaker-customization artists (Khaleej Times, Jul 31 2025)", "Celebrity adopters named: Ranveer Singh, Jay-Z, Sonam Kapoor, Pharrell, Shawn Mendes (per Khaleej Times)", "International custom pricing: ~AED 400 to AED 1,000+ per pair (per Khaleej Times) \u2014 supports export pricing", "Nike x Nor Black Nor White bandhani collab shows big brands embracing Indian custom aesthetics"]'::jsonb, '["customization", "international", "celebrity", "pricing", "khaleej-times"]'::jsonb, 'Global', 'Sneakers', 'summarized', 'market-research', now()),
('https://homegrown.co.in/homegrown-explore/6-indian-sneaker-customisers-you-need-to-know', 'kg_intel_homegrown_s_indian_sneaker_customiser_ro', 'web', 'Homegrown''s Indian sneaker-customiser roundup: competitor landscape and price points', 'Homegrown''s June 8, 2021 explainer ''6 Indian Sneaker Customisers You Need To Know'' maps the independent customizer scene: CHE by Chaitanya Dixit (Mumbai, INR 3,000-9,000, stocked at Superkicks), Sneakaboo (Noida, INR 1,500+), Mana Custom Art, Lazy Jojo (online Converse customs at INR 1,999 with free shipping), Mel''s Make by graffiti artist Melroy Pamak (Mumbai), and Shoes Your Daddy by Sugandha Tyagi (Delhi, INR 2,500-3,000) — all prices as listed by Homegrown in June 2021. The piece frames sneaker culture''s evolution from ''a sign of resistance'' into a tool of self-expression, per Homegrown. Most rivals are solo Instagram-order artists in the INR 1,500-9,000 band, which contrasts with Knickgasm''s scaled multi-artisan production model.', '["Independent customizers price INR 1,500-9,000 per pair (per Homegrown, Jun 2021)", "Rivals are mostly solo artists taking orders via Instagram/Facebook DMs (per Homegrown)", "CHE customs stocked at Superkicks stores \u2014 customizer-retailer distribution exists (per Homegrown)", "Competitive gap: no rival in the roundup operates a scaled artisan-network model"]'::jsonb, '["competitors", "customization", "pricing", "homegrown"]'::jsonb, 'IN', 'Sneakers', 'summarized', 'market-research', now()),
('https://www.business-standard.com/amp/content/press-releases-ani/why-anime-merch-spending-is-exploding-as-india-goes-mainstream-126060800554_1.html', 'kg_intel_anime_merch_demand_in_india_180m_fanbase', 'web', 'Anime merch demand in India: ~180M fanbase, 47% of The Souled Store''s revenue from merch', 'A June 2025 industry piece carried by Business Standard (ANI press release — treat attribution accordingly) reports India''s anime fanbase at roughly 180 million people, overwhelmingly Gen Z, per Brand License/Indian Retailer as cited in the article. India recorded ~41% anime viewership penetration with 30%+ growth between 2020 and 2025, ranking third globally behind Japan and China, per the same article. Merchandise reportedly accounts for 47% of The Souled Store''s revenue with a 160% repeat-purchase rate, and licensed anime SKUs sell at ~INR 1,000 vs INR 850 for original designs, per the Business Standard piece. Homegrown players named include The Souled Store, Bewakoof, Comicsense and Anime Devta, with Celio (Naruto) and Uniqlo launching anime collections in India — directly relevant to Knickgasm''s anime-themed custom sneaker and jacket lines.', '["~180M Indian anime fans, skewing Gen Z (per Brand License/Indian Retailer, cited in Business Standard, Jun 2025)", "~41% anime viewership penetration; 30%+ growth 2020-2025; #3 globally (per same article)", "Merch = 47% of The Souled Store revenue; 160% repeat-purchase rate (per Business Standard piece)", "Licensed anime SKUs command ~18% price premium over original designs (INR 1,000 vs 850)", "Caveat: source is an ANI press-release distribution, not independent reporting"]'::jsonb, '["anime", "merch", "gen-z", "demand", "licensing"]'::jsonb, 'IN', 'Sneakers', 'summarized', 'market-research', now()),
('https://www.theestablished.com/style/sneakers/why-sneaker-speciality-stores-are-the-go-to-choice-for-sneakerheads-and-first-time-buyers-alike', 'kg_intel_competitor_scale_vegnonveg_a_inr_100cr_b', 'web', 'Competitor scale: VegNonVeg a INR 100Cr+ business, 65% online; Superkicks in 5 cities', 'The Established''s July 11, 2023 feature on India''s speciality sneaker stores describes VegNonVeg (launched 2016 by Abhineet Singh with Anand Ahuja and Emilia Bergmans) as ''a business worth over a hundred crore,'' with ~65% of sales online and 30-35% of sales from tier-2/tier-3 cities, per The Established. VegNonVeg''s customer mix per the same piece: 60% first-time sneaker buyers, ~30% returning for a second purchase. Superkicks, founded 2018 in Mumbai by Sangeet Paryani, operates stores across Mumbai, Delhi, Bengaluru, Hyderabad and Pune per its own site and Tracxn profile, and remains unfunded per Tracxn. These multi-brand retailers are channel comps (and potential retail partners), not direct customization rivals — CHE customs have been stocked at Superkicks per Homegrown.', '["VegNonVeg: INR 100Cr+ business, 65% online sales, 30-35% from tier-2/3 cities (per The Established, Jul 2023)", "60% of VegNonVeg buyers are first-time sneaker buyers; ~30% repeat (per The Established)", "Superkicks: founded 2018 Mumbai, stores in 5 cities, unfunded (per Tracxn/superkicks.in)", "Speciality retail is a viable distribution channel for customizers (CHE x Superkicks precedent)"]'::jsonb, '["competitors", "retail", "vegnonveg", "superkicks", "channel"]'::jsonb, 'IN', 'Sneakers', 'summarized', 'market-research', now()),
('https://gulfnews.com/photos/entertainment/meet-sneakerheads-of-bollywood-ranveer-singh-sonam-kapoor-ananya-panday-and-more-1.1647874203178', 'kg_intel_celebrity_and_hip_hop_fuel_indian_sneake', 'web', 'Celebrity and hip-hop fuel Indian sneaker culture: Bollywood sneakerheads as demand drivers', 'Gulf News'' photo feature on Bollywood sneakerheads documents Ranveer Singh, Sonam Kapoor and Ananya Panday among celebrities publicly building sneaker collections, with Singh known for an over-the-top collection including Adidas x Jeremy Scott winged pairs, per Gulf News (March 2022). Broader coverage (The Established, 10 Hills Studio) describes Indian sneaker culture as strongly celebrity-driven, with stars like Ranveer Singh and Karan Johar wearing Jordans, Dunks and Yeezys and resellers kitting out celebrities including Deepika Padukone and Akshay Kumar. Indian hip-hop artists Divine, Emiway Bantai and Naezy have embedded sneakers in music videos and performances, per Neeman''s culture blog. This celebrity flywheel is the demand engine behind customization — and Knickgasm''s own organically-acquired celebrity clients (Shraddha Kapoor, Hardik Pandya, Rohit Sharma per Business Today, Sep 2025) plug directly into it.', '["Bollywood sneakerheads documented: Ranveer Singh, Sonam Kapoor, Ananya Panday (per Gulf News)", "Resellers reported dressing Ranveer Singh, Deepika Padukone, Akshay Kumar (per The Established coverage)", "Indian hip-hop (Divine, Emiway Bantai, Naezy) embeds sneaker culture in music videos (per Neeman''s blog)", "Celebrity visibility is the top-of-funnel driver for custom sneaker demand in India"]'::jsonb, '["celebrity", "bollywood", "hip-hop", "culture", "demand-drivers"]'::jsonb, 'IN', 'Sneakers', 'summarized', 'market-research', now())
